(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.02-t*0.25)*18 + Math.sin(x*0.016+t*0.33)*12;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx*0.025+sy*0.01+t*0.5)*8;
  const w2y = Math.cos(sy*0.025-sx*0.01-t*0.45)*8;
  const fx = sx + w2x, fy = sy + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*60,40+Math.cos(t*0.65+1)*40,0.11,2.1],
    [400+Math.cos(t*0.55+2)*70,200+Math.sin(t*0.75+4)*50,0.05,2.8],
    [200+Math.sin(t*0.25+5)*90,220+Math.cos(t*0.85+3)*60,0.13,1.4],
    [300+Math.cos(t*0.7+0.5)*80,30+Math.sin(t*0.5+2)*70,0.09,2.0]
  ];
  let aS=0,iS=0,aH=0,iH=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS+=Math.sin(d*f-t*sp); iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aH+=Math.sin(d*f*1.8-t*sp*1.3+0.8); iH+=Math.sin(d*f*1.2+t*sp*0.9+2.3);
  }
  const n=src.length, act=aS/n, inh=iS/n, actH=aH/n, inhH=iH/n;
  const bg=(Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1))/2+Math.sin((fx+fy)*0.12+t*2.5)*0.2+Math.sin((fx-fy)*0.1-t*2)*0.2+Math.sin(fx*0.007*fy*0.0001+t*1.8)*0.15;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2), ang=Math.atan2(fy-cy,fx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4+Math.sin(dist*0.08-ang*2-t*2.2)*0.2+Math.sin(dist*0.03+ang*6-t*0.8)*0.15;
  const moire=Math.sin(dist*0.12-t*1.5)*Math.sin(dist*0.1+ang*2-t*1.1)*0.3;
  const r1=Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const r2=Math.tanh((actH-inhH*0.6+moire)*2.8);
  const cell=Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15)+Math.sin((fx+fy)*0.1+t)*0.5)*1.5)*0.3;
  const hex=Math.sin(fx*0.12+Math.sin(fy*0.1)*0.5)*Math.sin(fy*0.12+Math.sin(fx*0.1)*0.5);
  const feedback=Math.sin(r1*3.5+r2*2)*0.15;
  const blend=r1*0.45+r2*0.2+cell*0.15+hex*0.12+feedback*0.08;
  const v=blend*0.5+0.5;
  const vig=1.0-Math.sqrt((x-cx)**2+(y-cy)**2)/380*0.25;
  const pal=[[5,10,45],[10,35,85],[15,70,120],[20,115,135],[30,155,140],[80,175,120],[160,190,80],[210,195,60],[230,160,50],[220,110,55],[195,65,60],[150,40,55],[90,25,50],[45,15,45],[5,10,45]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const absR=Math.abs(r1), edge=absR>0.75?1.0+(absR-0.75)*1.2:1.0;
  const spec=Math.max(0,r2)*0.25;
  const pulse=0.85+Math.sin(t*0.8+dist*0.02)*0.1+Math.sin(r1*Math.PI)*0.15;
  const lum=Math.max(0,(pulse*edge+spec)*vig);
  return[Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum)|0,Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum)|0,Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum)|0];
}
